export type Locale = "zh" | "en" | "ja";
export type TranslationKey = keyof typeof zh;

/** Resolve the UI locale from the host WebView/browser language list. */
export function detectSystemLocale(): Locale {
  const candidates = typeof navigator !== "undefined"
    ? (navigator.languages?.length ? navigator.languages : [navigator.language])
    : [];
  for (const candidate of candidates) {
    const normalized = candidate.toLowerCase().replace("_", "-");
    if (normalized.startsWith("zh")) return "zh";
    if (normalized.startsWith("ja")) return "ja";
    if (normalized.startsWith("en")) return "en";
  }
  return "en";
}

interface I18nContextProps {
  locale: Locale;
  t: (key: TranslationKey, vars?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nContextProps | undefined>(undefined);

export const I18nProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [locale, setLocale] = useState<Locale>(() => detectSystemLocale());
  const [ready, setReady] = useState(false);

  const loadLang = () => {
    getSettings()
      .then((s) => {
        if (s.language_auto) {
          setLocale(detectSystemLocale());
        } else if (s.language === "en" || s.language === "zh" || s.language === "ja") {
          setLocale(s.language);
        }
      })
      .catch(console.error)
      .finally(() => {
        setReady(true);
      });
  };

  useEffect(() => {
    loadLang();

    window.addEventListener("settings-changed", loadLang);
    return () => {
      window.removeEventListener("settings-changed", loadLang);
    };
  }, []);

  const t = (key: TranslationKey, vars?: Record<string, string | number>): string => {
    const dict = locale === "zh" ? zh : locale === "ja" ? ja : en;
    let str: string = dict[key] || en[key] || zh[key] || key;
    if (vars) {
      str = str.replace(/\{(\w+)\}/g, (_, name) =>
        name in vars ? String(vars[name]) : `{${name}}`,
      );
    }
    return str;
  };

  if (!ready) {
    // 渲染极简背景占位符以杜绝闪烁 (FOUC)
    return <div className="min-h-screen bg-app-bg" />;
  }

  return (
    <I18nContext.Provider value={{ locale, t }}>
      {children}
    </I18nContext.Provider>
  );
};

export const useI18n = () => {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error("useI18n must be used within an I18nProvider");
  }
  return context;
};
